CREATE TABLE zhuangtaibiao ( -- 状态表
  row_id INTEGER PRIMARY KEY, -- 行号
  shengming INTEGER NOT NULL DEFAULT 100, -- 生命
  jinbi INTEGER NOT NULL DEFAULT 10, -- 金币
  kuozhanshuju TEXT NOT NULL DEFAULT '{}' -- _扩展数据
);

CREATE TABLE beibaobiao ( -- 背包表
  row_id INTEGER PRIMARY KEY, -- 行号
  neirong TEXT NOT NULL DEFAULT '' -- 内容
);

CREATE TABLE guanxibiao ( -- 关系表
  row_id INTEGER PRIMARY KEY, -- 行号
  mingcheng TEXT NOT NULL DEFAULT '' UNIQUE, -- 名称
  haogan INTEGER NOT NULL DEFAULT 0, -- 好感
  kuozhanshuju TEXT NOT NULL DEFAULT '{}' -- _扩展数据
);

CREATE TABLE guanxi_rizhibiao ( -- 关系_日志表
  row_id INTEGER PRIMARY KEY, -- 行号
  guanxi_mingcheng TEXT NOT NULL DEFAULT '', -- 关系_名称
  neirong TEXT NOT NULL DEFAULT '' -- 内容
);
